export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdsList = [];
  let allThresholdsPassed = true;

  Object.entries(thresholds).forEach(([metricId, min]) => {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score ?? null;
    const passed = score !== null && score >= min;
    if (!passed) {
      allThresholdsPassed = false;
    }
    thresholdsList.push({
      metric: metricId,
      min,
      score,
      passed
    });
  });

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdsList.length > 0) {
    report.passed = allThresholdsPassed;
    report.thresholds = thresholdsList;
  }

  return report;
}

