  it('marks report as failed when threshold is not met', () => {
    const evaluations = runEvaluations({
      outputs: ['apple', 'banana'],
      references: ['apple', 'banana']
    });
    const thresholds = {
      exact_match: 0.99
    };
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.99,
      passed: false
    });
  });

  it('marks threshold as failed when metric score is null', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });
    const thresholds = {
      exact_match: 0.5
    };
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      score: null,
      passed: false
    });
  });
});

